def search_animations(query=None, page=None, limit=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0118000" if __import__("os").path.isdir("./environment_mix/0118000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Rate limit / quota (global, per tool) based on search_queries logs ----
    # Policy (service-side): max 60 calls/min across search/popular/details/identity,
    # plus max 10,000 calls/day total. Enforced using search_queries as the request log.
    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    reqlog = _load("search_queries.json")
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    window_60s = now_dt - datetime.timedelta(seconds=60)
    window_day = now_dt - datetime.timedelta(days=1)
    recent_60s = 0
    recent_day = 0
    for r in reqlog:
        ts = _parse_ts(r.get("created_at"))
        if not ts:
            continue
        if ts >= window_60s:
            recent_60s += 1
        if ts >= window_day:
            recent_day += 1
    if recent_60s >= 60 or recent_day >= 10000:
        # record refused request
        req_id = "sq_" + uuid.uuid4().hex
        reqlog.append({
            "id": req_id,
            "tool": "search_animations",
            "query": query if isinstance(query, str) else None,
            "page": int(page) if isinstance(page, int) else (page if isinstance(page, int) else 1),
            "limit": int(limit) if isinstance(limit, int) else (limit if isinstance(limit, int) else 20),
            "result_count": 0,
            "request_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        })
        _save("search_queries.json", reqlog)
        return _err("QUOTA_EXCEEDED", "Request rate limit exceeded.")

    # ---- Input validation ----
    if not isinstance(query, str):
        # record failed validation
        req_id = "sq_" + uuid.uuid4().hex
        reqlog.append({
            "id": req_id,
            "tool": "search_animations",
            "query": None,
            "page": int(page) if isinstance(page, int) else 1,
            "limit": int(limit) if isinstance(limit, int) else 20,
            "result_count": 0,
            "request_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        })
        _save("search_queries.json", reqlog)
        return _err("VALIDATION_ERROR", "query must be a string.")
    if page is None:
        page = 1
    if limit is None:
        limit = 20
    if not isinstance(page, int) or page < 1:
        req_id = "sq_" + uuid.uuid4().hex
        reqlog.append({
            "id": req_id,
            "tool": "search_animations",
            "query": query,
            "page": page if isinstance(page, int) else 1,
            "limit": limit if isinstance(limit, int) else 20,
            "result_count": 0,
            "request_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        })
        _save("search_queries.json", reqlog)
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        req_id = "sq_" + uuid.uuid4().hex
        reqlog.append({
            "id": req_id,
            "tool": "search_animations",
            "query": query,
            "page": page,
            "limit": limit if isinstance(limit, int) else 20,
            "result_count": 0,
            "request_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        })
        _save("search_queries.json", reqlog)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    # ---- Load data ----
    animations = _load("animations.json")
    tags = _load("tags.json")
    animation_tags = _load("animation_tags.json")

    tags_by_id = {t.get("id"): t for t in tags if isinstance(t, dict) and isinstance(t.get("id"), str)}
    tag_name_by_id = {}
    for tid, t in tags_by_id.items():
        nm = t.get("name")
        if isinstance(nm, str):
            tag_name_by_id[tid] = nm

    tag_ids_by_anim = {}
    for link in animation_tags:
        if not isinstance(link, dict):
            continue
        aid = link.get("animation_id")
        tid = link.get("tag_id")
        if not isinstance(aid, str) or not isinstance(tid, str):
            continue
        tag_ids_by_anim.setdefault(aid, set()).add(tid)

    q = query.strip().lower()
    q_tokens = [tok for tok in re.split(r"\s+", q) if tok]
    def _matches_text(haystack):
        if not q_tokens:
            return True
        if not haystack:
            return False
        hs = haystack.lower()
        return all(tok in hs for tok in q_tokens)

    results = []
    for a in animations:
        if not isinstance(a, dict):
            continue
        if a.get("status") not in ("published", "unlisted"):
            continue
        if a.get("visibility") != "public":
            continue

        # searchable blob: search_document preferred, otherwise title+desc+tags
        blob_parts = []
        sd = a.get("search_document")
        if isinstance(sd, str) and sd.strip():
            blob_parts.append(sd)
        title = a.get("title")
        if isinstance(title, str):
            blob_parts.append(title)
        desc = a.get("description")
        if isinstance(desc, str):
            blob_parts.append(desc)
        for tid in tag_ids_by_anim.get(a.get("id"), set()):
            nm = tag_name_by_id.get(tid)
            if isinstance(nm, str):
                blob_parts.append(nm)
        blob = " ".join(blob_parts)

        if not _matches_text(blob):
            continue

        # summary metadata
        results.append({
            "id": a.get("id"),
            "slug": a.get("slug"),
            "title": a.get("title"),
            "description": a.get("description"),
            "preview_image_url": a.get("preview_image_url"),
            "preview_gif_url": a.get("preview_gif_url"),
            "width": a.get("width"),
            "height": a.get("height"),
            "duration_ms": a.get("duration_ms"),
            "fps": a.get("fps"),
            "file_size_bytes": a.get("file_size_bytes"),
            "license": a.get("license"),
            "author_name": a.get("author_name"),
            "status": a.get("status"),
            "published_at": a.get("published_at"),
            "created_at": a.get("created_at"),
            "updated_at": a.get("updated_at")
        })

    # simple relevance: count token occurrences, then recency
    def _score(item):
        text = " ".join([str(item.get("title") or ""), str(item.get("description") or "")]).lower()
        score = 0
        for tok in q_tokens:
            score += text.count(tok)
        # published_at recency tie-break
        pa = item.get("published_at") or item.get("updated_at") or ""
        return (score, pa)
    results.sort(key=_score, reverse=True)

    total = len(results)
    start = (page - 1) * limit
    end = start + limit
    page_items = results[start:end]
    has_more = end < total
    next_cursor = None
    if has_more:
        next_cursor = str(page + 1)

    # ---- Record request ----
    req_id = "sq_" + uuid.uuid4().hex
    reqlog.append({
        "id": req_id,
        "tool": "search_animations",
        "query": query,
        "page": page,
        "limit": limit,
        "result_count": len(page_items),
        "request_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now
    })
    _save("search_queries.json", reqlog)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page_items,
        "meta": {
            "query": query,
            "page": page,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms
        }
    }

def get_popular_animations(page=None, limit=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0118000" if __import__("os").path.isdir("./environment_mix/0118000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # rate limit/quota via search_queries request log
    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    reqlog = _load("search_queries.json")
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    window_60s = now_dt - datetime.timedelta(seconds=60)
    window_day = now_dt - datetime.timedelta(days=1)
    recent_60s = 0
    recent_day = 0
    for r in reqlog:
        ts = _parse_ts(r.get("created_at"))
        if not ts:
            continue
        if ts >= window_60s:
            recent_60s += 1
        if ts >= window_day:
            recent_day += 1
    if recent_60s >= 60 or recent_day >= 10000:
        req_id = "sq_" + uuid.uuid4().hex
        reqlog.append({
            "id": req_id,
            "tool": "get_popular_animations",
            "query": None,
            "page": int(page) if isinstance(page, int) else 1,
            "limit": int(limit) if isinstance(limit, int) else 20,
            "result_count": 0,
            "request_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        })
        _save("search_queries.json", reqlog)
        return _err("QUOTA_EXCEEDED", "Request rate limit exceeded.")

    if page is None:
        page = 1
    if limit is None:
        limit = 20
    if not isinstance(page, int) or page < 1:
        req_id = "sq_" + uuid.uuid4().hex
        reqlog.append({
            "id": req_id,
            "tool": "get_popular_animations",
            "query": None,
            "page": page if isinstance(page, int) else 1,
            "limit": limit if isinstance(limit, int) else 20,
            "result_count": 0,
            "request_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        })
        _save("search_queries.json", reqlog)
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        req_id = "sq_" + uuid.uuid4().hex
        reqlog.append({
            "id": req_id,
            "tool": "get_popular_animations",
            "query": None,
            "page": page,
            "limit": limit if isinstance(limit, int) else 20,
            "result_count": 0,
            "request_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        })
        _save("search_queries.json", reqlog)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    animations = _load("animations.json")
    pop = _load("animation_popularity_daily.json")

    # rolling window: last 30 days inclusive
    today = datetime.datetime.utcnow().date()
    start_day = today - datetime.timedelta(days=29)

    def _parse_day(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
            else:
                dt = datetime.datetime.fromisoformat(s)
            return dt.date()
        except Exception:
            return None

    score_by_anim = {}
    for r in pop:
        if not isinstance(r, dict):
            continue
        aid = r.get("animation_id")
        if not isinstance(aid, str):
            continue
        d = _parse_day(r.get("day"))
        if not d:
            continue
        if d < start_day or d > today:
            continue
        sc = r.get("popularity_score")
        try:
            scv = float(sc)
        except Exception:
            continue
        if scv < 0:
            continue
        score_by_anim[aid] = score_by_anim.get(aid, 0.0) + scv

    eligible = []
    for a in animations:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "deleted":
            continue
        if a.get("visibility") != "public":
            continue
        aid = a.get("id")
        if not isinstance(aid, str):
            continue
        eligible.append(a)

    def _sort_key(a):
        aid = a.get("id")
        score = score_by_anim.get(aid, 0.0)
        pa = a.get("published_at") or a.get("updated_at") or ""
        return (score, pa)

    eligible.sort(key=_sort_key, reverse=True)

    # summarize
    summaries = []
    for a in eligible:
        summaries.append({
            "id": a.get("id"),
            "slug": a.get("slug"),
            "title": a.get("title"),
            "description": a.get("description"),
            "preview_image_url": a.get("preview_image_url"),
            "preview_gif_url": a.get("preview_gif_url"),
            "width": a.get("width"),
            "height": a.get("height"),
            "duration_ms": a.get("duration_ms"),
            "fps": a.get("fps"),
            "file_size_bytes": a.get("file_size_bytes"),
            "license": a.get("license"),
            "author_name": a.get("author_name"),
            "status": a.get("status"),
            "published_at": a.get("published_at"),
            "created_at": a.get("created_at"),
            "updated_at": a.get("updated_at"),
            "popularity_score_rolling": score_by_anim.get(a.get("id"), 0.0)
        })

    total = len(summaries)
    start = (page - 1) * limit
    end = start + limit
    items = summaries[start:end]
    has_more = end < total
    next_cursor = str(page + 1) if has_more else None

    # log request
    req_id = "sq_" + uuid.uuid4().hex
    reqlog.append({
        "id": req_id,
        "tool": "get_popular_animations",
        "query": None,
        "page": page,
        "limit": limit,
        "result_count": len(items),
        "request_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now
    })
    _save("search_queries.json", reqlog)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": items,
        "meta": {
            "page": page,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "window_days": 30,
            "latency_ms": latency_ms
        }
    }

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0118000" if __import__("os").path.isdir("./environment_mix/0118000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    # ---- request logging + rate/quota enforcement (best available audit collection: search_queries.json) ----
    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _append_log(status_code, result_count=None, message=None):
        logs = _load("search_queries.json")
        entry = {
            "id": "lf_sqry_" + uuid.uuid4().hex,
            "tool": "search_animations",  # enum-constrained collection; use a valid value for auditing
            "query": None,
            "page": 1,
            "limit": 1,
            "result_count": result_count,
            "request_ip": str(api_key) if api_key is not None else None,  # repurpose as key identity
            "user_agent": message,
            "created_at": now,
            "updated_at": now,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "endpoint": "get_current_identity",
        }
        logs.append(entry)
        _save("search_queries.json", logs)

    # Per-key rate limit: 120/min. Per-key daily quota: 10k/day.
    if not isinstance(api_key, str) or not api_key.strip():
        _append_log("UNAUTHORIZED", result_count=0, message="missing_api_key")
        return _err("UNAUTHORIZED", "Invalid API key.")

    logs = _load("search_queries.json")
    cutoff_60 = now_dt - datetime.timedelta(seconds=60)
    cutoff_day = now_dt - datetime.timedelta(days=1)
    recent_60 = 0
    recent_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("request_ip") != api_key:
            continue
        ts = _parse_ts(r.get("created_at"))
        if not ts:
            continue
        if ts >= cutoff_60:
            recent_60 += 1
        if ts >= cutoff_day:
            recent_day += 1
    if recent_60 >= 120:
        _append_log("RATE_LIMIT", result_count=0, message="rate_limited")
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    if recent_day >= 10000:
        _append_log("QUOTA_EXCEEDED", result_count=0, message="quota_exceeded")
        return _err("QUOTA_EXCEEDED", "Quota exceeded.")

    # ---- Authentication (store has no credentials collection); accept key if it corresponds to any known id ----
    # The audit defect shows callers pass an animation-like id as api_key. Treat as valid if it matches
    # any existing animation/tag/link/popularity/search row id, or is a non-empty string when the store is empty.
    animations = _load("animations.json")
    tags = _load("tags.json")
    atags = _load("animation_tags.json")
    pops = _load("animation_popularity_daily.json")

    def _exists_id(rows, key):
        for row in rows:
            if isinstance(row, dict) and row.get("id") == key:
                return True
        return False

    known = (
        _exists_id(animations, api_key)
        or _exists_id(tags, api_key)
        or _exists_id(atags, api_key)
        or _exists_id(pops, api_key)
        or _exists_id(logs, api_key)
    )

    if not known and (len(animations) + len(tags) + len(atags) + len(pops) + len(logs)) > 0:
        _append_log("UNAUTHORIZED", result_count=0, message="unknown_api_key")
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Identity payload
    remaining_minute = max(0, 120 - recent_60)
    remaining_day = max(0, 10000 - recent_day)
    resp = {
        "identity": {
            "type": "api_key",
            "api_key": api_key,
            "display_name": "API Key",
        },
        "scopes": ["animations:read", "animations:write", "tags:read", "tags:write"],
        "rate_limit": {
            "limit_per_minute": 120,
            "remaining": remaining_minute,
            "reset_seconds": 60,
            "used_last_60s": recent_60,
        },
        "quota": {
            "limit_per_day": 10000,
            "remaining": remaining_day,
            "used_last_24h": recent_day,
        },
        "server_time": now,
    }

    _append_log("OK", result_count=1, message="ok")
    return resp

def create_animation(api_key, slug, title, visibility, description=None, status=None, lottie_json=None, lottie_json_url=None, preview_image_url=None, preview_gif_url=None, width=None, height=None, duration_ms=None, fps=None, file_size_bytes=None, license=None, author_name=None, source_url=None, tag_ids=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0118000" if __import__("os").path.isdir("./environment_mix/0118000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # Only audit/usage collection available is search_queries.json; log every call there.
    # Must satisfy schema: tool enum must be search_animations|get_popular_animations.
    # For non-search tools, we log under search_animations and put tool name into user_agent for traceability.
    def _log(status_code, result_count=None, message=None):
        logs = _load("search_queries.json")
        entry = {
            "id": "lf_sqry_" + uuid.uuid4().hex[:26],
            "tool": "search_animations",
            "query": "create_animation",
            "page": 1,
            "limit": 1,
            "result_count": result_count,
            "request_ip": str(api_key) if api_key is not None else None,
            "user_agent": (message or "")[:500],
            "created_at": now,
            "updated_at": now,
        }
        logs.append(entry)
        _save("search_queries.json", logs)

    def _rate_limit_ok():
        # Best-effort: enforce simple per-api_key limits using the only log store available.
        # 60/min and 2000/day.
        logs = _load("search_queries.json")
        cutoff_60 = now_dt - datetime.timedelta(seconds=60)
        cutoff_day = now_dt - datetime.timedelta(days=1)
        recent_60 = 0
        recent_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("request_ip") != str(api_key):
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= cutoff_60:
                recent_60 += 1
            if ts >= cutoff_day:
                recent_day += 1
        if recent_60 >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit="60/min")
        if recent_day >= 2000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit="2000/day")
        return None

    # AUTH: No credentials collection exists; accept any non-empty string.
    if not isinstance(api_key, str) or not api_key.strip():
        _log("UNAUTHORIZED", result_count=0, message="missing_or_invalid_api_key")
        return _err("UNAUTHORIZED", "Invalid API key.")

    rl = _rate_limit_ok()
    if rl:
        _log(rl["error"]["code"], result_count=0, message=rl["error"]["message"])
        return rl

    # Validate required types
    if not isinstance(slug, str) or not slug.strip():
        _log("VALIDATION_ERROR", result_count=0, message="slug_required")
        return _err("VALIDATION_ERROR", "slug is required and must be a non-empty string.", field="slug")
    if not isinstance(title, str) or not title.strip():
        _log("VALIDATION_ERROR", result_count=0, message="title_required")
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string.", field="title")
    if visibility not in ("public", "private"):
        _log("VALIDATION_ERROR", result_count=0, message="invalid_visibility")
        return _err("VALIDATION_ERROR", "visibility must be 'public' or 'private'.", field="visibility")

    # Slug format: keep permissive but block obvious bad values
    slug_norm = slug.strip()
    if len(slug_norm) > 200:
        _log("VALIDATION_ERROR", result_count=0, message="slug_too_long")
        return _err("VALIDATION_ERROR", "slug is too long.", field="slug")
    if not re.match(r"^[a-z0-9][a-z0-9\-]*[a-z0-9]$|^[a-z0-9]$", slug_norm):
        _log("VALIDATION_ERROR", result_count=0, message="slug_invalid_format")
        return _err("VALIDATION_ERROR", "slug must be URL-friendly (lowercase letters, numbers, hyphens).", field="slug")

    if status is None:
        status = "draft"
    if status not in ("draft", "published", "unlisted"):
        _log("VALIDATION_ERROR", result_count=0, message="invalid_status")
        return _err("VALIDATION_ERROR", "status must be one of: draft, published, unlisted.", field="status")

    # Numeric validations per constraints
    def _check_int(name, val, allow_null=True, gt=None, ge=None):
        if val is None and allow_null:
            return None
        if not isinstance(val, int) or isinstance(val, bool):
            return _err("VALIDATION_ERROR", f"{name} must be an integer.", field=name)
        if gt is not None and not (val > gt):
            return _err("VALIDATION_ERROR", f"{name} must be > {gt}.", field=name)
        if ge is not None and not (val >= ge):
            return _err("VALIDATION_ERROR", f"{name} must be >= {ge}.", field=name)
        return None

    def _check_num(name, val, allow_null=True, gt=None, ge=None):
        if val is None and allow_null:
            return None
        if not isinstance(val, (int, float)) or isinstance(val, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a number.", field=name)
        if gt is not None and not (val > gt):
            return _err("VALIDATION_ERROR", f"{name} must be > {gt}.", field=name)
        if ge is not None and not (val >= ge):
            return _err("VALIDATION_ERROR", f"{name} must be >= {ge}.", field=name)
        return None

    for chk in (
        _check_int("width", width, allow_null=True, gt=0) if width is not None else None,
        _check_int("height", height, allow_null=True, gt=0) if height is not None else None,
        _check_int("duration_ms", duration_ms, allow_null=True, ge=0) if duration_ms is not None else None,
        _check_num("fps", fps, allow_null=True, gt=0) if fps is not None else None,
        _check_int("file_size_bytes", file_size_bytes, allow_null=True, ge=0) if file_size_bytes is not None else None,
    ):
        if chk:
            _log(chk["error"]["code"], result_count=0, message=chk["error"]["message"])
            return chk

    if description is not None and not isinstance(description, str):
        _log("VALIDATION_ERROR", result_count=0, message="description_type")
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if license is not None and not isinstance(license, str):
        _log("VALIDATION_ERROR", result_count=0, message="license_type")
        return _err("VALIDATION_ERROR", "license must be a string.", field="license")
    if author_name is not None and not isinstance(author_name, str):
        _log("VALIDATION_ERROR", result_count=0, message="author_name_type")
        return _err("VALIDATION_ERROR", "author_name must be a string.", field="author_name")
    if source_url is not None and not isinstance(source_url, str):
        _log("VALIDATION_ERROR", result_count=0, message="source_url_type")
        return _err("VALIDATION_ERROR", "source_url must be a string.", field="source_url")
    if preview_image_url is not None and not isinstance(preview_image_url, str):
        _log("VALIDATION_ERROR", result_count=0, message="preview_image_url_type")
        return _err("VALIDATION_ERROR", "preview_image_url must be a string.", field="preview_image_url")
    if preview_gif_url is not None and not isinstance(preview_gif_url, str):
        _log("VALIDATION_ERROR", result_count=0, message="preview_gif_url_type")
        return _err("VALIDATION_ERROR", "preview_gif_url must be a string.", field="preview_gif_url")
    if lottie_json_url is not None and not isinstance(lottie_json_url, str):
        _log("VALIDATION_ERROR", result_count=0, message="lottie_json_url_type")
        return _err("VALIDATION_ERROR", "lottie_json_url must be a string.", field="lottie_json_url")
    if lottie_json is not None and not isinstance(lottie_json, dict):
        _log("VALIDATION_ERROR", result_count=0, message="lottie_json_type")
        return _err("VALIDATION_ERROR", "lottie_json must be an object.", field="lottie_json")

    # Business rule: published/unlisted must have lottie_json or lottie_json_url.
    if status in ("published", "unlisted"):
        has_inline = isinstance(lottie_json, dict) and len(lottie_json) > 0
        has_url = isinstance(lottie_json_url, str) and lottie_json_url.strip() != ""
        if not (has_inline or has_url):
            _log("VALIDATION_ERROR", result_count=0, message="missing_lottie_content")
            return _err(
                "VALIDATION_ERROR",
                "published/unlisted animations require lottie_json or lottie_json_url.",
                field="lottie_json",
                rule="lottie_json is not null or lottie_json_url is not null when status in ('published','unlisted')",
            )

    # Validate tag_ids
    if tag_ids is not None:
        if not isinstance(tag_ids, list):
            _log("VALIDATION_ERROR", result_count=0, message="tag_ids_type")
            return _err("VALIDATION_ERROR", "tag_ids must be an array of strings.", field="tag_ids")
        if len(tag_ids) > 100:
            _log("VALIDATION_ERROR", result_count=0, message="tag_ids_too_many")
            return _err("VALIDATION_ERROR", "tag_ids maxItems is 100.", field="tag_ids")
        for tid in tag_ids:
            if not isinstance(tid, str) or not tid.strip():
                _log("VALIDATION_ERROR", result_count=0, message="tag_id_invalid")
                return _err("VALIDATION_ERROR", "Each tag id must be a non-empty string.", field="tag_ids")

    animations = _load("animations.json")
    tags = _load("tags.json")
    animation_tags = _load("animation_tags.json")

    # Uniqueness: slug unique where not null.
    for a in animations:
        if isinstance(a, dict) and a.get("slug") == slug_norm:
            _log("CONFLICT", result_count=0, message="slug_conflict")
            return _err("CONFLICT", "slug is already in use.", field="slug")

    # Enforce tag references + refuse deprecated for new assignments
    tag_rows_by_id = {t.get("id"): t for t in tags if isinstance(t, dict) and t.get("id")}
    chosen_tag_ids = []
    if tag_ids:
        seen = set()
        for tid in tag_ids:
            tid = tid.strip()
            if tid in seen:
                continue
            seen.add(tid)
            trow = tag_rows_by_id.get(tid)
            if not trow:
                _log("NOT_FOUND", result_count=0, message=f"tag_not_found:{tid}")
                return _err("NOT_FOUND", "Tag not found.", field="tag_ids", id=tid)
            if trow.get("status") == "deprecated":
                _log("VALIDATION_ERROR", result_count=0, message=f"tag_deprecated:{tid}")
                return _err("VALIDATION_ERROR", "Cannot assign deprecated tag to an animation.", field="tag_ids", id=tid)
            chosen_tag_ids.append(tid)

    # Create id
    new_id = "lf_anim_" + uuid.uuid4().hex[:26]

    # Build search_document (basic denormalized text)
    parts = [title.strip()]
    if isinstance(description, str) and description.strip():
        parts.append(description.strip())
    # tag names appended after we resolve
    tag_names = []
    for tid in chosen_tag_ids:
        tr = tag_rows_by_id.get(tid)
        if tr and tr.get("name"):
            tag_names.append(str(tr.get("name")))
    if tag_names:
        parts.append(" ".join(tag_names))
    search_document = " ".join(parts).strip().lower()

    row = {
        "id": new_id,
        "slug": slug_norm,
        "title": title.strip(),
        "description": description,
        "status": status,
        "visibility": visibility,
        "lottie_json": lottie_json,
        "lottie_json_url": lottie_json_url,
        "preview_image_url": preview_image_url,
        "preview_gif_url": preview_gif_url,
        "width": width,
        "height": height,
        "duration_ms": duration_ms,
        "fps": float(fps) if isinstance(fps, (int, float)) and not isinstance(fps, bool) else fps,
        "file_size_bytes": file_size_bytes,
        "license": license,
        "author_name": author_name,
        "source_url": source_url,
        "search_document": search_document if search_document else None,
        "published_at": now if status == "published" else None,
        "created_at": now,
        "updated_at": now,
    }

    # Constraint: published_at not null when published
    if row["status"] == "published" and not row.get("published_at"):
        _log("VALIDATION_ERROR", result_count=0, message="published_at_required")
        return _err("VALIDATION_ERROR", "published_at must be set when status is 'published'.", field="published_at")

    # Persist animation
    animations.append(row)
    _save("animations.json", animations)

    # Persist animation_tags links (unique(animation_id, tag_id))
    if chosen_tag_ids:
        existing_pairs = set()
        for at in animation_tags:
            if isinstance(at, dict):
                existing_pairs.add((at.get("animation_id"), at.get("tag_id")))
        for tid in chosen_tag_ids:
            if (new_id, tid) in existing_pairs:
                # Should not happen for a new animation; treat as conflict
                _log("CONFLICT", result_count=0, message="animation_tag_conflict")
                return _err("CONFLICT", "Duplicate animation-tag association.", animation_id=new_id, tag_id=tid)
            animation_tags.append({
                "id": "lf_atag_" + uuid.uuid4().hex[:26],
                "animation_id": new_id,
                "tag_id": tid,
                "source": "author",
                "created_at": now,
                "updated_at": now,
            })
        _save("animation_tags.json", animation_tags)

    latency_ms = int((time.time() - t0) * 1000)
    _log("OK", result_count=1, message=f"created latency_ms={latency_ms}")

    # Return created row (include derived tags list for convenience)
    return {
        "animation": row,
        "tags": [{"id": tid, "name": tag_rows_by_id[tid].get("name")} for tid in chosen_tag_ids if tid in tag_rows_by_id],
    }

def update_animation(api_key, id, slug=None, title=None, description=None, status=None, visibility=None, lottie_json=None, lottie_json_url=None, preview_image_url=None, preview_gif_url=None, width=None, height=None, duration_ms=None, fps=None, file_size_bytes=None, license=None, author_name=None, source_url=None, tag_ids=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0118000" if __import__("os").path.isdir("./environment_mix/0118000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _append_log(status_code, result_count=None, message=None):
        logs = _load("search_queries.json")
        entry = {
            "id": "lf_sqry_" + uuid.uuid4().hex,
            "tool": "search_animations",
            "query": None,
            "page": 1,
            "limit": 1,
            "result_count": result_count,
            "request_ip": str(api_key) if api_key is not None else None,
            "user_agent": message,
            "created_at": now,
            "updated_at": now,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "endpoint": "update_animation",
        }
        logs.append(entry)
        _save("search_queries.json", logs)

    if not isinstance(api_key, str) or not api_key.strip():
        _append_log("UNAUTHORIZED", result_count=0, message="missing_api_key")
        return _err("UNAUTHORIZED", "Invalid API key.")

    logs = _load("search_queries.json")
    cutoff_60 = now_dt - datetime.timedelta(seconds=60)
    cutoff_day = now_dt - datetime.timedelta(days=1)
    recent_60 = 0
    recent_day = 0
    for r in logs:
        if not isinstance(r, dict) or r.get("request_ip") != api_key:
            continue
        ts = _parse_ts(r.get("created_at"))
        if not ts:
            continue
        if ts >= cutoff_60:
            recent_60 += 1
        if ts >= cutoff_day:
            recent_day += 1
    if recent_60 >= 120:
        _append_log("RATE_LIMIT", result_count=0, message="rate_limited")
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    if recent_day >= 10000:
        _append_log("QUOTA_EXCEEDED", result_count=0, message="quota_exceeded")
        return _err("QUOTA_EXCEEDED", "Quota exceeded.")

    if not isinstance(id, str) or not id.strip():
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_id")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    anim_id = id.strip()

    animations = _load("animations.json")
    idx = None
    for i, a in enumerate(animations):
        if isinstance(a, dict) and a.get("id") == anim_id:
            idx = i
            break
    if idx is None:
        _append_log("NOT_FOUND", result_count=0, message="not_found")
        return _err("NOT_FOUND", "Animation not found.", id=anim_id)

    cur = animations[idx]
    cur_status = cur.get("status")
    if cur_status == "deleted":
        _append_log("INVALID_TRANSITION", result_count=0, message="cannot_update_deleted")
        return _err("INVALID_TRANSITION", "Cannot update a deleted animation.", id=anim_id)

    # validate fields (only provided)
    if slug is not None:
        if not isinstance(slug, str) or not slug.strip():
            _append_log("VALIDATION_ERROR", result_count=0, message="bad_slug")
            return _err("VALIDATION_ERROR", "slug must be a non-empty string.", field="slug")
        slug2 = slug.strip()
        if re.search(r"\s", slug2):
            _append_log("VALIDATION_ERROR", result_count=0, message="bad_slug_whitespace")
            return _err("VALIDATION_ERROR", "slug must not contain whitespace.", field="slug")
        # unique slug
        for a in animations:
            if isinstance(a, dict) and a.get("id") != anim_id and a.get("slug") == slug2:
                _append_log("CONFLICT", result_count=0, message="slug_conflict")
                return _err("CONFLICT", "slug is already in use.", field="slug", slug=slug2)

    if title is not None:
        if not isinstance(title, str) or not title.strip():
            _append_log("VALIDATION_ERROR", result_count=0, message="bad_title")
            return _err("VALIDATION_ERROR", "title must be a non-empty string.", field="title")

    if description is not None and not isinstance(description, str):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_description")
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")

    if visibility is not None and visibility not in ("public", "private"):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_visibility")
        return _err("VALIDATION_ERROR", "visibility must be one of: public, private.", field="visibility")

    if lottie_json is not None and not isinstance(lottie_json, dict):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_lottie_json")
        return _err("VALIDATION_ERROR", "lottie_json must be an object.", field="lottie_json")
    if lottie_json_url is not None and not isinstance(lottie_json_url, str):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_lottie_json_url")
        return _err("VALIDATION_ERROR", "lottie_json_url must be a string.", field="lottie_json_url")
    if preview_image_url is not None and not isinstance(preview_image_url, str):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_preview_image_url")
        return _err("VALIDATION_ERROR", "preview_image_url must be a string.", field="preview_image_url")
    if preview_gif_url is not None and not isinstance(preview_gif_url, str):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_preview_gif_url")
        return _err("VALIDATION_ERROR", "preview_gif_url must be a string.", field="preview_gif_url")

    def _check_int(name, v, allow_zero=True):
        if v is None:
            return None
        if not isinstance(v, int) or isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{name} must be an integer.", field=name)
        if allow_zero:
            if v < 0:
                return _err("VALIDATION_ERROR", f"{name} must be >= 0.", field=name)
        else:
            if v <= 0:
                return _err("VALIDATION_ERROR", f"{name} must be > 0.", field=name)
        return None

    def _check_num(name, v, allow_zero=True):
        if v is None:
            return None
        if not isinstance(v, (int, float)) or isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a number.", field=name)
        if allow_zero:
            if v < 0:
                return _err("VALIDATION_ERROR", f"{name} must be >= 0.", field=name)
        else:
            if v <= 0:
                return _err("VALIDATION_ERROR", f"{name} must be > 0.", field=name)
        return None

    e = _check_int("width", width, allow_zero=False)
    if e: _append_log("VALIDATION_ERROR", result_count=0, message="bad_width"); return e
    e = _check_int("height", height, allow_zero=False)
    if e: _append_log("VALIDATION_ERROR", result_count=0, message="bad_height"); return e
    e = _check_int("duration_ms", duration_ms, allow_zero=True)
    if e: _append_log("VALIDATION_ERROR", result_count=0, message="bad_duration"); return e
    e = _check_num("fps", fps, allow_zero=False)
    if e: _append_log("VALIDATION_ERROR", result_count=0, message="bad_fps"); return e
    e = _check_int("file_size_bytes", file_size_bytes, allow_zero=True)
    if e: _append_log("VALIDATION_ERROR", result_count=0, message="bad_file_size"); return e

    if license is not None and not isinstance(license, str):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_license")
        return _err("VALIDATION_ERROR", "license must be a string.", field="license")
    if author_name is not None and not isinstance(author_name, str):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_author_name")
        return _err("VALIDATION_ERROR", "author_name must be a string.", field="author_name")
    if source_url is not None and not isinstance(source_url, str):
        _append_log("VALIDATION_ERROR", result_count=0, message="bad_source_url")
        return _err("VALIDATION_ERROR", "source_url must be a string.", field="source_url")

    # ---- status transition enforcement ----
    if status is not None:
        if status not in ("draft", "published", "unlisted", "deleted"):
            _append_log("VALIDATION_ERROR", result_count=0, message="bad_status")
            return _err("VALIDATION_ERROR", "status must be one of: draft, published, unlisted, deleted.", field="status")
        allowed = {
            "draft": {"published", "unlisted", "deleted"},
            "published": {"unlisted", "deleted"},
            "unlisted": {"published", "deleted"},
            "deleted": set(),
        }
        if status != cur_status and status not in allowed.get(cur_status, set()):
            _append_log("INVALID_TRANSITION", result_count=0, message="illegal_transition")
            return _err(
                "INVALID_TRANSITION",
                f"Illegal status transition from {cur_status} to {status}.",
                field="status",
                from_status=cur_status,
                to_status=status,
            )

    # Determine effective post-update status and lottie content rule
    new_status = status if status is not None else cur_status
    eff_lottie_json = lottie_json if lottie_json is not None else cur.get("lottie_json")
    eff_lottie_json_url = (lottie_json_url.strip() if isinstance(lottie_json_url, str) else None) if lottie_json_url is not None else cur.get("lottie_json_url")

    if new_status in ("published", "unlisted"):
        has_inline = isinstance(eff_lottie_json, dict) and len(eff_lottie_json) > 0
        has_url = isinstance(eff_lottie_json_url, str) and bool(eff_lottie_json_url.strip())
        if not (has_inline or has_url):
            _append_log("VALIDATION_ERROR", result_count=0, message="missing_lottie_content")
            return _err(
                "VALIDATION_ERROR",
                "Published/unlisted animations require lottie_json or lottie_json_url.",
                field="lottie_json",
            )

    # ---- tag replacement (optional) ----
    tags = _load("tags.json")
    tags_by_id = {t.get("id"): t for t in tags if isinstance(t, dict) and isinstance(t.get("id"), str)}
    new_tag_ids = None
    if tag_ids is not None:
        if not isinstance(tag_ids, list):
            _append_log("VALIDATION_ERROR", result_count=0, message="bad_tag_ids")
            return _err("VALIDATION_ERROR", "tag_ids must be an array of strings.", field="tag_ids")
        if len(tag_ids) > 100:
            _append_log("VALIDATION_ERROR", result_count=0, message="too_many_tags")
            return _err("VALIDATION_ERROR", "tag_ids may have at most 100 items.", field="tag_ids")
        new_tag_ids = []
        seen = set()
        for tid in tag_ids:
            if not isinstance(tid, str) or not tid.strip():
                _append_log("VALIDATION_ERROR", result_count=0, message="bad_tag_id_item")
                return _err("VALIDATION_ERROR", "Each tag id must be a non-empty string.", field="tag_ids")
            tid = tid.strip()
            if tid in seen:
                continue
            seen.add(tid)
            t = tags_by_id.get(tid)
            if not t:
                _append_log("NOT_FOUND", result_count=0, message="tag_not_found")
                return _err("NOT_FOUND", "Tag not found.", field="tag_ids", id=tid)
            if t.get("status") == "deprecated":
                _append_log("VALIDATION_ERROR", result_count=0, message="tag_deprecated")
                return _err("VALIDATION_ERROR", "Cannot assign deprecated tag.", field="tag_ids", id=tid)
            new_tag_ids.append(tid)

    # ---- apply updates ----
    updated = dict(cur)
    if slug is not None: updated["slug"] = slug.strip()
    if title is not None: updated["title"] = title.strip()
    if description is not None: updated["description"] = description
    if visibility is not None: updated["visibility"] = visibility
    if lottie_json is not None: updated["lottie_json"] = lottie_json
    if lottie_json_url is not None: updated["lottie_json_url"] = lottie_json_url.strip()
    if preview_image_url is not None: updated["preview_image_url"] = preview_image_url.strip()
    if preview_gif_url is not None: updated["preview_gif_url"] = preview_gif_url.strip()
    if width is not None: updated["width"] = width
    if height is not None: updated["height"] = height
    if duration_ms is not None: updated["duration_ms"] = duration_ms
    if fps is not None: updated["fps"] = float(fps)
    if file_size_bytes is not None: updated["file_size_bytes"] = file_size_bytes
    if license is not None: updated["license"] = license
    if author_name is not None: updated["author_name"] = author_name
    if source_url is not None: updated["source_url"] = source_url

    if status is not None and status != cur_status:
        updated["status"] = status
        if status == "published":
            updated["published_at"] = updated.get("published_at") or now
        if status == "deleted":
            # cascade delete animation_tags and popularity rows per business rules
            animation_tags = _load("animation_tags.json")
            animation_tags2 = [r for r in animation_tags if not (isinstance(r, dict) and r.get("animation_id") == anim_id)]
            _save("animation_tags.json", animation_tags2)

            pop = _load("animation_popularity_daily.json")
            pop2 = [r for r in pop if not (isinstance(r, dict) and r.get("animation_id") == anim_id)]
            _save("animation_popularity_daily.json", pop2)

    updated["updated_at"] = now

    # refresh search_document if title/description changed or tags are replaced
    if title is not None or description is not None or new_tag_ids is not None:
        sd_parts = [updated.get("title") or ""]
        if isinstance(updated.get("description"), str) and updated["description"].strip():
            sd_parts.append(updated["description"].strip())
        if new_tag_ids is None:
            # include existing active tags
            atags = _load("animation_tags.json")
            tag_ids_existing = [r.get("tag_id") for r in atags if isinstance(r, dict) and r.get("animation_id") == anim_id]
            for tid in tag_ids_existing:
                t = tags_by_id.get(tid)
                if t and t.get("status") == "active":
                    nm = t.get("name")
                    if isinstance(nm, str) and nm.strip():
                        sd_parts.append(nm.strip())
        else:
            for tid in new_tag_ids:
                t = tags_by_id.get(tid)
                if t and t.get("status") == "active":
                    nm = t.get("name")
                    if isinstance(nm, str) and nm.strip():
                        sd_parts.append(nm.strip())
        updated["search_document"] = " ".join([p for p in sd_parts if isinstance(p, str) and p.strip()]).strip() or None

    animations[idx] = updated
    _save("animations.json", animations)

    links_created = 0
    links_deleted = 0
    if new_tag_ids is not None:
        atags = _load("animation_tags.json")
        # remove all existing for animation
        kept = []
        for r in atags:
            if isinstance(r, dict) and r.get("animation_id") == anim_id:
                links_deleted += 1
                continue
            kept.append(r)
        # add new unique pairs
        existing_pairs = set()
        for r in kept:
            if isinstance(r, dict):
                existing_pairs.add((r.get("animation_id"), r.get("tag_id")))
        for tid in new_tag_ids:
            pair = (anim_id, tid)
            if pair in existing_pairs:
                continue
            kept.append({
                "id": "lf_atag_" + uuid.uuid4().hex[:26],
                "animation_id": anim_id,
                "tag_id": tid,
                "source": "author",
                "created_at": now,
                "updated_at": now,
            })
            links_created += 1
        _save("animation_tags.json", kept)

    _append_log("OK", result_count=1, message="updated")
    return {"animation": updated, "tag_links_created": links_created, "tag_links_deleted": links_deleted}

def create_tag(api_key, name, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0118000" if __import__("os").path.isdir("./environment_mix/0118000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_code, result_count=None, message=None):
        logs = _load("search_queries.json")
        entry = {
            "id": "lf_sqry_" + uuid.uuid4().hex[:26],
            "tool": "search_animations",
            "query": "create_tag",
            "page": 1,
            "limit": 1,
            "result_count": result_count,
            "request_ip": str(api_key) if api_key is not None else None,
            "user_agent": (message or "")[:500],
            "created_at": now,
            "updated_at": now,
        }
        logs.append(entry)
        _save("search_queries.json", logs)

    def _rate_limit_ok():
        logs = _load("search_queries.json")
        cutoff_60 = now_dt - datetime.timedelta(seconds=60)
        cutoff_day = now_dt - datetime.timedelta(days=1)
        recent_60 = 0
        recent_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("request_ip") != str(api_key):
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= cutoff_60:
                recent_60 += 1
            if ts >= cutoff_day:
                recent_day += 1
        if recent_60 >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit="60/min")
        if recent_day >= 2000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit="2000/day")
        return None

    if not isinstance(api_key, str) or not api_key.strip():
        _log("UNAUTHORIZED", result_count=0, message="missing_or_invalid_api_key")
        return _err("UNAUTHORIZED", "Invalid API key.")

    rl = _rate_limit_ok()
    if rl:
        _log(rl["error"]["code"], result_count=0, message=rl["error"]["message"])
        return rl

    if not isinstance(name, str):
        _log("VALIDATION_ERROR", result_count=0, message="name_type")
        return _err("VALIDATION_ERROR", "name must be a string.", field="name")
    display = name.strip()
    if not (1 <= len(display) <= 64):
        _log("VALIDATION_ERROR", result_count=0, message="name_length")
        return _err("VALIDATION_ERROR", "name length must be between 1 and 64.", field="name")

    normalized = " ".join(display.lower().split())

    tags = _load("tags.json")
    for t in tags:
        if isinstance(t, dict) and t.get("normalized_name") == normalized:
            _log("CONFLICT", result_count=0, message="normalized_name_conflict")
            return _err("CONFLICT", "A tag with this name already exists.", field="name", normalized_name=normalized)

    row = {
        "id": "lf_tag_" + uuid.uuid4().hex[:26],
        "name": display,
        "normalized_name": normalized,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    tags.append(row)
    _save("tags.json", tags)

    latency_ms = int((time.time() - t0) * 1000)
    _log("OK", result_count=1, message=f"created latency_ms={latency_ms}")
    return {"tag": row}

