        _save("search_queries.json", logs)

    def _rate_limit_ok():
        logs = _load("search_queries.json")
        cutoff_60 = now_dt - datetime.timedelta(seconds=60)
        cutoff_day = now_dt - datetime.timedelta(days=1)
        recent_60 = 0
        recent_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("request_ip") != str(api_key):
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
