    if name is None and status is None:
        _log("VALIDATION_ERROR", result_count=0, message="no_fields")
        return _err("VALIDATION_ERROR", "At least one of 'name' or 'status' must be provided.")

    if status is not None and status not in ("active", "deprecated"):
        _log("VALIDATION_ERROR", result_count=0, message="invalid_status")
        return _err("VALIDATION_ERROR", "status must be 'active' or 'deprecated'.", field="status")

    tags = _load("tags.json")
    idx = None
    for i, t in enumerate(tags):
        if isinstance(t, dict) and t.get("id") == id:
            idx = i
            break
    if idx is None:
        _log("NOT_FOUND", result_count=0, message="tag_not_found")
        return _err("NOT_FOUND", "Tag not found.", id=id)

    row = tags[idx]

    # Validate and apply name update with uniqueness on normalized_name
    if name is not None:
        if not isinstance(name, str):
            _log("VALIDATION_ERROR", result_count=0, message="name_type")
            return _err("VALIDATION_ERROR", "name must be a string.", field="name")
