                _log("CONFLICT", result_count=0, message="normalized_name_conflict")
                return _err("CONFLICT", "A tag with this name already exists.", field="name", normalized_name=normalized)
        row["name"] = display
        row["normalized_name"] = normalized

    # Lifecycle transition enforcement: active -> deprecated only; deprecated cannot change back
    if status is not None:
        current = row.get("status")
        if current == "deprecated" and status == "active":
            _log("INVALID_TRANSITION", result_count=0, message="deprecated_to_active_forbidden")
            return _err("INVALID_TRANSITION", "Cannot transition tag from deprecated back to active.", from_status=current, to_status=status)
        if current == "active" and status == "deprecated":
            row["status"] = "deprecated"
        elif status == current:
            # idempotent
            pass
        elif current == "active" and status == "active":
            pass
        elif current == "deprecated" and status == "deprecated":
            pass
        else:
            _log("INVALID_TRANSITION", result_count=0, message="invalid_transition")
            return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=current, to_status=status)

    row["updated_at"] = now
    tags[idx] = row
    _save("tags.json", tags)

    latency_ms = int((time.time() - t0) * 1000)
    _log("OK", result_count=1, message=f"updated latency_ms={latency_ms}")
    return {"tag": row}

def list_tags(api_key, query=None, status=None, page=None, limit=None, sort=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0118000" if __import__("os").path.isdir("./environment_mix/0118000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers for request logging + quota/rate limiting ---
    def _ensure_list(v):
        return v if isinstance(v, list) else []

    def _log_request(endpoint, credential, status_code, latency_ms, extra=None):
        extra = extra or {}
        logs = _ensure_list(_load("request_logs.json"))
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": credential,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": now,
        }
        row.update({k: v for k, v in extra.items() if k not in row})
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit(credential):
        """
        Enforce rate limits if a rate_limits collection exists.
        Expected row shapes (best-effort):
          { "id":..., "credential":<api_key or key_id>, "limit_per_minute": int }
          or { "id":..., "credential":..., "requests_per_minute": int }
          or { "scope":"global", "limit_per_minute": int }
        If collection missing/empty, do not limit.
        """
        limits = _ensure_list(_load("rate_limits.json"))
        if not limits:
            return None  # no limit configured
        per_min = None
        # match credential-specific first
        for r in limits:
            if r.get("credential") == credential or r.get("api_key") == credential or r.get("key") == credential:
                per_min = r.get("limit_per_minute", r.get("requests_per_minute"))
                break
        # fallback global
        if per_min is None:
            for r in limits:
                if r.get("scope") in ("global", "default") or r.get("credential") in (None, "", "global", "default"):
                    per_min = r.get("limit_per_minute", r.get("requests_per_minute"))
                    if per_min is not None:
                        break
        if per_min is None:
            return None

        try:
            per_min = int(per_min)
        except Exception:
            return None
        if per_min <= 0:
            return _err("RATE_LIMIT", "Rate limit exceeded.")

        logs = _ensure_list(_load("request_logs.json"))
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        cnt = 0
        for e in logs[::-1]:
            ts = e.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            if e.get("credential") == credential:
                cnt += 1
        if cnt >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=per_min)
        return None

    def _check_quota(credential):
        """
        Enforce monthly quota if a quotas collection exists.
        Expected row shapes (best-effort):
          { "credential":..., "monthly_limit": int } or { "monthly_requests": int }
        If missing/empty, do not enforce.
        """
        quotas = _ensure_list(_load("quotas.json"))
        if not quotas:
            return None
        limit = None
        for q in quotas:
            if q.get("credential") == credential or q.get("api_key") == credential or q.get("key") == credential:
                limit = q.get("monthly_limit", q.get("monthly_requests"))
                break
        if limit is None:
            for q in quotas:
                if q.get("scope") in ("global", "default") or q.get("credential") in (None, "", "global", "default"):
                    limit = q.get("monthly_limit", q.get("monthly_requests"))
                    if limit is not None:
                        break
        if limit is None:
            return None
        try:
            limit = int(limit)
        except Exception:
            return None
        if limit <= 0:
            return _err("QUOTA_EXCEEDED", "Quota exceeded.", monthly_limit=limit)

        logs = _ensure_list(_load("request_logs.json"))
        utcnow = datetime.datetime.utcnow().replace(microsecond=0)
        month_start = utcnow.replace(day=1, hour=0, minute=0, second=0)
        cnt = 0
        for e in logs:
            if e.get("credential") != credential:
                continue
            ts = e.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= month_start:
                cnt += 1
        if cnt >= limit:
            return _err("QUOTA_EXCEEDED", "Quota exceeded.", monthly_limit=limit)
        return None

    # --- validate inputs ---
    if not isinstance(api_key, str) or not api_key.strip():
        # log even failed calls
        latency = (time.time() - t0) * 1000
        _log_request("list_tags", api_key if isinstance(api_key, str) else None, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    api_key = api_key.strip()

    if query is not None and not isinstance(query, str):
        latency = (time.time() - t0) * 1000
        _log_request("list_tags", api_key, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "query must be a string when provided.")
    if status is not None:
        if not isinstance(status, str):
            latency = (time.time() - t0) * 1000
            _log_request("list_tags", api_key, "VALIDATION_ERROR", latency)
            return _err("VALIDATION_ERROR", "status must be a string when provided.")
        if status not in ("active", "deprecated"):
            latency = (time.time() - t0) * 1000
            _log_request("list_tags", api_key, "VALIDATION_ERROR", latency)
            return _err("VALIDATION_ERROR", "status must be one of: active, deprecated.")
    if page is None:
        page = 1
    if limit is None:
        limit = 20
    if sort is None:
        sort = "name_asc"

    if not isinstance(page, int) or page < 1:
        latency = (time.time() - t0) * 1000
        _log_request("list_tags", api_key, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        latency = (time.time() - t0) * 1000
        _log_request("list_tags", api_key, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if sort not in ("name_asc", "name_desc", "created_at_desc", "updated_at_desc"):
        latency = (time.time() - t0) * 1000
        _log_request("list_tags", api_key, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "sort must be one of: name_asc, name_desc, created_at_desc, updated_at_desc.")

    # --- authenticate api_key (best-effort; ambient auth allowed but api_key parameter required by tool) ---
    # The store may include api_keys.json (or keys.json) with plaintext tokens.
    cred_row = None
    for fname in ("api_keys.json", "keys.json", "credentials.json"):
        rows = _ensure_list(_load(fname))
        if not rows:
            continue
        for r in rows:
            # Match either by id or by client-visible key/token value fields.
            if api_key == r.get("id") or api_key == r.get("api_key") or api_key == r.get("key") or api_key == r.get("token") or api_key == r.get("value"):
                # If present, require active/enabled
                st = r.get("status") or r.get("state") or "active"
                if isinstance(st, str) and st.lower() in ("revoked", "disabled", "inactive", "deleted"):
                    continue
                cred_row = r
                break
        if cred_row:
            break

    # If no credential store exists at all, treat api_key as valid (offline server may omit auth collections).
    any_cred_store = False
    for fname in ("api_keys.json", "keys.json", "credentials.json"):
        if os.path.exists(os.path.join(_DB, fname)):
            any_cred_store = True
            break
    if any_cred_store and cred_row is None:
        latency = (time.time() - t0) * 1000
        _log_request("list_tags", api_key, "UNAUTHORIZED", latency)
        return _err("UNAUTHORIZED", "Invalid API key.")

    # --- enforce rate limits / quota ---
    rl = _check_rate_limit(api_key)
    if rl is not None:
        latency = (time.time() - t0) * 1000
        _log_request("list_tags", api_key, rl["error"]["code"], latency)
        return rl
    qt = _check_quota(api_key)
    if qt is not None:
        latency = (time.time() - t0) * 1000
        _log_request("list_tags", api_key, qt["error"]["code"], latency)
        return qt

    # --- load and filter tags ---
    tags = _ensure_list(_load("tags.json"))

    qnorm = None
    if isinstance(query, str):
        q = query.strip()
        if q:
            qnorm = q.lower()

    filtered = []
    for t in tags:
        if not isinstance(t, dict):
            continue
        if status is not None and t.get("status") != status:
            continue
        if qnorm is not None:
            name = t.get("name") or ""
            nname = t.get("normalized_name") or ""
            if not (isinstance(name, str) and qnorm in name.lower()) and not (isinstance(nname, str) and qnorm in nname.lower()):
                continue
        filtered.append(t)

    # --- sort ---
    def _safe_str(x):
        return x if isinstance(x, str) else ""
    def _safe_dt(x):
        # keep as string; iso sorts lexicographically when consistent
        return _safe_str(x)

    if sort == "name_asc":
        filtered.sort(key=lambda r: (_safe_str(r.get("normalized_name")).lower(), _safe_str(r.get("name")).lower(), _safe_str(r.get("id"))))
    elif sort == "name_desc":
        filtered.sort(key=lambda r: (_safe_str(r.get("normalized_name")).lower(), _safe_str(r.get("name")).lower(), _safe_str(r.get("id"))), reverse=True)
    elif sort == "created_at_desc":
        filtered.sort(key=lambda r: (_safe_dt(r.get("created_at")), _safe_str(r.get("id"))), reverse=True)
    elif sort == "updated_at_desc":
        filtered.sort(key=lambda r: (_safe_dt(r.get("updated_at")), _safe_str(r.get("id"))), reverse=True)

    total = len(filtered)
    start = (page - 1) * limit
    end = start + limit
    page_items = filtered[start:end] if start < total else []
    has_more = end < total
    next_cursor = str(page + 1) if has_more else None

    # --- log call with result_count (observability) ---
    latency = (time.time() - t0) * 1000
    _log_request(
        "list_tags",
        api_key,
        "OK",
        latency,
        extra={"result_count": len(page_items), "page": page, "limit": limit}
    )

    return {
        "data": page_items,
        "meta": {
            "page": page,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "status_filter": status,
            "query": query
        }
    }
